export function findMaxLength(values: number[]): number {
const first=new Map<number,number>([[0,-1]]);let balance=0,best=0;for(let i=0;i<values.length;i++){balance+=values[i]===1?1:-1;if(first.has(balance))best=Math.max(best,i-first.get(balance)!);else first.set(balance,i);}return best;
}
